import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_upper_triangular_matmul_detail {

constexpr int TILE = 16;

__global__ void cute_upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row = blockIdx.y * TILE + ty;
    const int col = blockIdx.x * TILE + tx;

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(N, N),
        make_stride(N, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(N, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(N, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(&As[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));

    auto sB = make_tensor(
        make_smem_ptr(&Bs[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));

    float acc = 0.0f;

    for (int k0 = 0; k0 < N; k0 += TILE) {
        const int a_col = k0 + tx;
        const int b_row = k0 + ty;

        if (row < N && a_col < N) {
            sA(ty, tx) = gA(row, a_col);
        } else {
            sA(ty, tx) = 0.0f;
        }

        if (b_row < N && col < N) {
            sB(ty, tx) = gB(b_row, col);
        } else {
            sB(ty, tx) = 0.0f;
        }

        __syncthreads();

        if (row < N && col < N && row <= col) {
            #pragma unroll
            for (int kk = 0; kk < TILE; ++kk) {
                const int global_k = k0 + kk;
                if (global_k >= row && global_k <= col && global_k < N) {
                    acc += sA(ty, kk) * sB(kk, tx);
                }
            }
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        gC(row, col) = (row <= col) ? acc : 0.0f;
    }
}

} // namespace cute_upper_triangular_matmul_detail

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must have dtype float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must have dtype float32");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(1) == B.size(0), "A and B dimensions must match");

    const int N = static_cast<int>(A.size(0));

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();
    auto C = torch::empty_like(A_contiguous);

    dim3 block(
        cute_upper_triangular_matmul_detail::TILE,
        cute_upper_triangular_matmul_detail::TILE);
    dim3 grid(
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE,
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_upper_triangular_matmul_detail::cute_upper_triangular_matmul_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        N);
    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CuTE upper-triangular matmul kernel launch failed");

    return C;
}
"""

cute_ext = load_inline(
    name="cute_upper_triangular_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_upper_triangular_matmul"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_upper_triangular_matmul(A, B)

